/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-004 — EIA (Evidence & Audit Agent)
 * src/cubio/agents/eia/evidenceAgent.ts
 *
 * Central sovereign orchestrator for AGENT-004 EIA.
 * Creates, validates, traces, and seals evidence generated by tasks, tests,
 * experiments, and peer agents (MEA, DRA, TGA, PMA).
 */

import {
  EIAAuditScope,
  EIAAuditReport,
  EIAEvidenceArtifact,
  EIAChainOfCustodyStep,
  EIASafetyStatus,
} from './types';
import { EIAArtifactIdentity } from './artifactIdentity';
import { EIAChainOfCustody } from './chainOfCustody';
import { EIADiscrepancyDetector } from './discrepancyDetector';
import { EIAAuditSealer } from './auditSealer';
import { EIARxEvidenceTracker } from './rxEvidence';
import { IS_ACTUATION_BLOCKED } from '../../intelligence/core/coreEngineContract';

export class EIAEvidenceAgent {
  public static readonly AGENT_ID = 'AGENT-004-EIA';
  public static readonly VERSION = '1.0.0';

  private readonly rootDir: string;
  private readonly identity: EIAArtifactIdentity;
  private readonly detector: EIADiscrepancyDetector;

  constructor(customRootDir?: string) {
    this.rootDir = customRootDir || process.cwd();
    this.identity = new EIAArtifactIdentity(this.rootDir);
    this.detector = new EIADiscrepancyDetector(this.rootDir);
  }

  /**
   * Primary entry point: Audits an incoming scope and produces a sealed EIAAuditReport.
   */
  public async auditEvidence(scope: EIAAuditScope): Promise<EIAAuditReport> {
    const startTimeMs = performance.now();

    // 1. Fail-closed scope validation
    if (!scope || typeof scope !== 'object' || !scope.taskId || !scope.objective) {
      throw new Error('[EIA_SCOPE_INVALID] Task ID and objective are mandatory for audit.');
    }

    // 2. Sovereign Actuation Lockout Assertion
    this.assertActuationLockout();

    const rxTracker = new EIARxEvidenceTracker(scope.taskId);

    // RX0: Intake
    rxTracker.recordRx0Intake(scope);

    // RX1: Artifact Discovery & Ingestion
    const artifacts: EIAEvidenceArtifact[] = scope.artifacts ? [...scope.artifacts] : [];
    rxTracker.recordRx1ArtifactDiscovery(artifacts.length);

    // RX2: Chain-of-Custody Tracking
    let custodySteps: readonly EIAChainOfCustodyStep[] = scope.custodySteps || [];
    if (custodySteps.length === 0 && scope.transitions && scope.transitions.length > 0) {
      // Build custody steps from transitions if custody steps not provided directly
      const chain = new EIAChainOfCustody();
      for (const tr of scope.transitions) {
        chain.addStep({
          stage: tr.toStage,
          action: `Transition to RX${tr.toStage}`,
          actor: tr.agentId,
          inputHash: tr.transitionHash,
          outputHash: tr.transitionHash,
          timestamp: tr.timestamp,
        });
      }
      custodySteps = chain.getSteps();
    }
    rxTracker.recordRx2ChainValidation(custodySteps.length);

    // RX3: Discrepancy & Drift Detection
    const discrepancies = this.detector.auditScope({
      ...scope,
      artifacts,
      custodySteps,
    });
    rxTracker.recordRx3DiscrepancyAudit(discrepancies.length);

    // RX4: Synthesis
    const hasCritical = discrepancies.some((d) => d.severity === 'CRITICAL');
    const hasWarning = discrepancies.some((d) => d.severity === 'WARNING');
    const tentativeStatus = hasCritical
      ? 'REJECTED_CORRUPTED'
      : hasWarning
      ? 'DISCREPANCY_FLAGGED'
      : 'CERTIFIED_SEALED';
    rxTracker.recordRx4Synthesis(tentativeStatus);

    const executionTimeMs = Number((performance.now() - startTimeMs).toFixed(2));

    // RX5: Sealing
    const report = EIAAuditSealer.sealAudit({
      taskId: scope.taskId,
      scope,
      artifacts,
      custodySteps,
      discrepancies,
      rxLifecycleId: rxTracker.getLifecycleId(),
      executionTimeMs,
    });

    rxTracker.sealLifecycle(report);
    return report;
  }

  /**
   * Helper to fingerprint a file directly via the agent's identity engine.
   */
  public fingerprintFile(relativePath: string) {
    return this.identity.fingerprintFile(relativePath);
  }

  /**
   * Helper to fingerprint a memory payload.
   */
  public fingerprintPayload(id: string, payload: unknown) {
    return this.identity.fingerprintPayload(id, payload);
  }

  /**
   * Returns the agent's current safety posture.
   */
  public getSafetyStatus(): EIASafetyStatus {
    return Object.freeze({
      isActuationBlocked: IS_ACTUATION_BLOCKED === true,
      isOfflineOnly: true,
      externalAiDetected: false,
    });
  }

  private assertActuationLockout(): void {
    if (IS_ACTUATION_BLOCKED !== true) {
      throw new Error(
        '[EIA_SAFETY_BREACH] Actuation lockout invariant violated: IS_ACTUATION_BLOCKED must be true.'
      );
    }
  }
}
